// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MergingPool} from "../src/MergingPool.sol";

contract InvMutTest is Test {
    MergingPool c;
    function setUp() public { c = new MergingPool(address(this), address(this), address(new __InvMutHandleStub())); }
    function testFuzz_property(address caller, uint256 newWinners) public {
        vm.assume(caller != address(this) && caller != address(0) && caller != address(c));
        vm.assume(newWinners != c.winnersPerPeriod());
        uint256 before = c.winnersPerPeriod();
        vm.prank(caller);
        try c.updateWinnersPerPeriod(newWinners) {
            // call must not succeed for a non-admin
            assertTrue(false);
        } catch {
            assertTrue(c.winnersPerPeriod() == before);
        }
    }
}
